1	//! Device-free output route planning. A plan is not a reservation, allocation,
2	//! modeset test or presentation result; all of those require backend transactions.
3	use serde::Serialize;
4	use std::collections::{BTreeMap, BTreeSet, VecDeque};
5	
6	pub const MAX_CONNECTORS: usize = 64;
7	pub const MAX_ENCODERS: usize = 128;
8	pub const MAX_CRTCS: usize = 32;
9	pub const MAX_PLANES: usize = 128;
10	pub const MAX_MODES: usize = 256;
11	pub const MAX_FORMATS: usize = 256;
12	
13	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize)]
14	pub struct Format {
15	    pub code: u32,
16	    // DRM modifiers are full-width values, including INVALID; never coerce to Linear.
17	    #[serde(serialize_with = "serialize_u64")]
18	    pub modifier: u64,
19	}
20	fn serialize_u64<S: serde::Serializer>(value: &u64, serializer: S) -> Result<S::Ok, S::Error> {
21	    serializer.serialize_str(&value.to_string())
22	}
23	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
24	pub enum Connection {
25	    Connected,
26	    Disconnected,
27	    Unknown,
28	}
29	#[derive(Clone, Debug)]
30	pub struct Connector {
31	    pub id: u32,
32	    pub connection: Connection,
33	    pub non_desktop: bool,
34	    pub encoders: Vec<u32>,
35	    pub current_encoder: Option<u32>,
36	    /// Original kernel order: selected indices refer to this exact snapshot.
37	    pub modes: Vec<Mode>,
38	}
39	#[derive(Clone, Debug)]
40	pub struct Encoder {
41	    pub id: u32,
42	    pub crtcs: Vec<u32>,
43	    pub current_crtc: Option<u32>,
44	}
45	#[derive(Clone, Debug)]
46	pub struct Plane {
47	    pub id: u32,
48	    pub crtcs: Vec<u32>,
49	    pub formats: Vec<Format>,
50	}
51	#[derive(Clone, Debug, Default)]
52	pub struct Topology {
53	    pub connectors: Vec<Connector>,
54	    pub encoders: Vec<Encoder>,
55	    pub crtcs: Vec<u32>,
56	    /// Primary planes only, as classified by the backend.
57	    pub planes: Vec<Plane>,
58	    pub render_formats: Vec<Format>,
59	}
60	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
61	pub struct Mode {
62	    pub width: u16,
63	    pub height: u16,
64	    pub hsync_start: u16,
65	    pub hsync_end: u16,
66	    pub htotal: u16,
67	    pub vsync_start: u16,
68	    pub vsync_end: u16,
69	    pub vtotal: u16,
70	    pub clock_khz: u32,
71	    pub vscan: u16,
72	    pub interlaced: bool,
73	    pub double_scan: bool,
74	    pub preferred: bool,
75	}
76	impl Mode {
77	    /// Rounded rational mHz, without relying on the kernel's integer-Hz label.
78	    pub fn refresh_millihz(self) -> Option<u32> {
79	        if self.width == 0
80	            || self.height == 0
81	            || self.clock_khz == 0
82	            || !(self.width <= self.hsync_start
83	                && self.hsync_start <= self.hsync_end
84	                && self.hsync_end <= self.htotal)
85	            || !(self.height <= self.vsync_start
86	                && self.vsync_start <= self.vsync_end
87	                && self.vsync_end <= self.vtotal)
88	        {
89	            return None;
90	        }
91	        let numerator = u64::from(self.clock_khz) * 1_000_000 * if self.interlaced { 2 } else { 1 };
92	        let denominator = u64::from(self.htotal)
93	            * u64::from(self.vtotal)
94	            * u64::from(self.vscan.max(1))
95	            * if self.double_scan { 2 } else { 1 };
96	        let refresh = (numerator + denominator / 2) / denominator;
97	        u32::try_from(refresh).ok().filter(|value| *value > 0)
98	    }
99	}
100	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
101	pub enum PlanError {
102	    Capacity,
103	    InvalidTopology,
104	}
105	impl std::fmt::Display for PlanError {
106	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
107	        write!(f, "output planning failed: {self:?}")
108	    }
109	}
110	impl std::error::Error for PlanError {}
111	#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
112	pub struct Assignment {
113	    pub connector: u32,
114	    pub encoder: u32,
115	    pub crtc: u32,
116	    pub primary_plane: u32,
117	    pub mode_index: usize,
118	    pub mode: Mode,
119	    pub refresh_millihz: u32,
120	    /// Exact renderer/plane intersection; allocation and KMS testing still required.
121	    pub candidate_formats: Vec<Format>,
122	}
123	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
124	pub enum UnassignedReason {
125	    Disconnected,
126	    UnknownConnection,
127	    NonDesktop,
128	    NoValidMode,
129	    NoCompatibleRoute,
130	}
131	#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
132	pub struct Unassigned {
133	    pub connector: u32,
134	    pub reason: UnassignedReason,
135	}
136	#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize)]
137	pub struct Plan {
138	    pub assignments: Vec<Assignment>,
139	    pub unassigned: Vec<Unassigned>,
140	}
141	fn unique_ids(ids: impl IntoIterator<Item = u32>, cap: usize) -> Result<BTreeSet<u32>, PlanError> {
142	    let mut set = BTreeSet::new();
143	    for id in ids {
144	        if id == 0 || !set.insert(id) {
145	            return Err(PlanError::InvalidTopology);
146	        }
147	        if set.len() > cap {
148	            return Err(PlanError::Capacity);
149	        }
150	    }
151	    Ok(set)
152	}
153	fn references(ids: &[u32], known: &BTreeSet<u32>) -> Result<(), PlanError> {
154	    let refs = unique_ids(ids.iter().copied(), known.len())?;
155	    if !refs.is_subset(known) {
156	        return Err(PlanError::InvalidTopology);
157	    }
158	    Ok(())
159	}
160	fn selected_mode(connector: &Connector) -> Option<(usize, Mode, u32)> {
161	    connector
162	        .modes
163	        .iter()
164	        .copied()
165	        .enumerate()
166	        .filter_map(|(index, mode)| mode.refresh_millihz().map(|refresh| (index, mode, refresh)))
167	        .max_by_key(|(index, mode, refresh)| {
168	            (
169	                mode.preferred,
170	                u32::from(mode.width) * u32::from(mode.height),
171	                *refresh,
172	                std::cmp::Reverse(*index),
173	            )
174	        })
175	}
176	#[derive(Clone)]
177	struct Edge {
178	    to: usize,
179	    reverse: usize,
180	    available: bool,
181	    forward: bool,
182	}
183	#[derive(Default)]
184	struct Graph {
185	    nodes: Vec<Vec<Edge>>,
186	}
187	impl Graph {
188	    fn node(&mut self) -> usize {
189	        let id = self.nodes.len();
190	        self.nodes.push(vec![]);
191	        id
192	    }
193	    fn edge(&mut self, from: usize, to: usize) {
194	        let reverse = self.nodes[to].len();
195	        let back = self.nodes[from].len();
196	        self.nodes[from].push(Edge {
197	            to,
198	            reverse,
199	            available: true,
200	            forward: true,
201	        });
202	        self.nodes[to].push(Edge {
203	            to: from,
204	            reverse: back,
205	            available: false,
206	            forward: false,
207	        });
208	    }
209	    fn split(&mut self) -> (usize, usize) {
210	        let a = self.node();
211	        let b = self.node();
212	        self.edge(a, b);
213	        (a, b)
214	    }
215	    fn flow(&mut self, source: usize, sink: usize) {
216	        loop {
217	            let mut parent = vec![None; self.nodes.len()];
218	            let mut queue = VecDeque::from([source]);
219	            parent[source] = Some((source, usize::MAX));
220	            while let Some(node) = queue.pop_front() {
221	                for (index, edge) in self.nodes[node].iter().enumerate() {
222	                    if edge.available && parent[edge.to].is_none() {
223	                        parent[edge.to] = Some((node, index));
224	                        queue.push_back(edge.to);
225	                    }
226	                }
227	            }
228	            if parent[sink].is_none() {
229	                break;
230	            }
231	            let mut node = sink;
232	            while node != source {
233	                let (from, index) = parent[node].expect("reachable augmenting path");
234	                let reverse = self.nodes[from][index].reverse;
235	                self.nodes[from][index].available = false;
236	                self.nodes[node][reverse].available = true;
237	                node = from;
238	            }
239	        }
240	    }
241	    fn used_to(&self, node: usize) -> Option<usize> {
242	        self.nodes[node]
243	            .iter()
244	            .find(|edge| edge.forward && !edge.available)
245	            .map(|edge| edge.to)
246	    }
247	}
248	/// Maximum-cardinality independent routes. Stable ID ordering and current-route
249	/// preference make ties deterministic; this is not minimum-disruption optimization.
250	pub fn plan(topology: &Topology) -> Result<Plan, PlanError> {
251	    // Reject before constructing the graph; no partial plan escapes on invalid data.
252	    if topology.connectors.len() > MAX_CONNECTORS
253	        || topology.encoders.len() > MAX_ENCODERS
254	        || topology.crtcs.len() > MAX_CRTCS
255	        || topology.planes.len() > MAX_PLANES
256	        || topology.render_formats.len() > MAX_FORMATS
257	        || topology
258	            .connectors
259	            .iter()
260	            .any(|c| c.modes.len() > MAX_MODES)
261	        || topology
262	            .planes
263	            .iter()
264	            .any(|p| p.formats.len() > MAX_FORMATS)
265	    {
266	        return Err(PlanError::Capacity);
267	    }
268	    let connectors = unique_ids(topology.connectors.iter().map(|c| c.id), MAX_CONNECTORS)?;
269	    let encoders = unique_ids(topology.encoders.iter().map(|e| e.id), MAX_ENCODERS)?;
270	    let crtcs = unique_ids(topology.crtcs.iter().copied(), MAX_CRTCS)?;
271	    let planes = unique_ids(topology.planes.iter().map(|p| p.id), MAX_PLANES)?;
272	    for c in &topology.connectors {
273	        references(&c.encoders, &encoders)?;
274	        if c.current_encoder.is_some_and(|id| !encoders.contains(&id)) {
275	            return Err(PlanError::InvalidTopology);
276	        }
277	    }
278	    for e in &topology.encoders {
279	        references(&e.crtcs, &crtcs)?;
280	        if e.current_crtc.is_some_and(|id| !crtcs.contains(&id)) {
281	            return Err(PlanError::InvalidTopology);
282	        }
283	    }
284	    for p in &topology.planes {
285	        references(&p.crtcs, &crtcs)?;
286	    }
287	    let mut graph = Graph::default();
288	    let source = graph.node();
289	    let sink = graph.node();
290	    let cn: BTreeMap<_, _> = connectors.iter().map(|id| (*id, graph.split())).collect();
291	    let en: BTreeMap<_, _> = encoders.iter().map(|id| (*id, graph.split())).collect();
292	    let rn: BTreeMap<_, _> = crtcs.iter().map(|id| (*id, graph.split())).collect();
293	    let pn: BTreeMap<_, _> = planes.iter().map(|id| (*id, graph.split())).collect();
294	    let mut result = Plan::default();
295	    let mut modes = BTreeMap::new();
296	    let by_connector: BTreeMap<_, _> = topology.connectors.iter().map(|c| (c.id, c)).collect();
297	    let by_encoder: BTreeMap<_, _> = topology.encoders.iter().map(|e| (e.id, e)).collect();
298	    let by_plane: BTreeMap<_, _> = topology.planes.iter().map(|p| (p.id, p)).collect();
299	    for (id, c) in &by_connector {
300	        let reason = match c.connection {
301	            Connection::Disconnected => Some(UnassignedReason::Disconnected),
302	            Connection::Unknown => Some(UnassignedReason::UnknownConnection),
303	            Connection::Connected if c.non_desktop => Some(UnassignedReason::NonDesktop),
304	            Connection::Connected => None,
305	        };
306	        let mode = selected_mode(c);
307	        if let Some(reason) =
308	            reason.or_else(|| mode.is_none().then_some(UnassignedReason::NoValidMode))
309	        {
310	            result.unassigned.push(Unassigned {
311	                connector: *id,
312	                reason,
313	            });
314	            continue;
315	        }
316	        modes.insert(*id, mode.expect("checked selected mode"));
317	        graph.edge(source, cn[id].0);
318	        let mut candidates = c.encoders.clone();
319	        candidates.sort_by_key(|id| (Some(*id) != c.current_encoder, *id));
320	        for encoder in candidates {
321	            graph.edge(cn[id].1, en[&encoder].0);
322	        }
323	    }
324	    for (id, e) in by_encoder {
325	        let mut candidates = e.crtcs.clone();
326	        candidates.sort_by_key(|id| (Some(*id) != e.current_crtc, *id));
327	        for crtc in candidates {
328	            graph.edge(en[&id].1, rn[&crtc].0);
329	        }
330	    }
331	    let render: BTreeSet<_> = topology.render_formats.iter().copied().collect();
332	    let mut formats = BTreeMap::new();
333	    for (id, p) in by_plane {
334	        let common: Vec<_> = p
335	            .formats
336	            .iter()
337	            .copied()
338	            .collect::<BTreeSet<_>>()
339	            .intersection(&render)
340	            .copied()
341	            .collect();
342	        if common.is_empty() {
343	            continue;
344	        }
345	        formats.insert(id, common);
346	        for crtc in &crtcs {
347	            if p.crtcs.contains(crtc) {
348	                graph.edge(rn[crtc].1, pn[&id].0);
349	            }
350	        }
351	        graph.edge(pn[&id].1, sink);
352	    }
353	    graph.flow(source, sink);
354	    for id in connectors {
355	        let Some((index, mode, refresh)) = modes.get(&id) else {
356	            continue;
357	        };
358	        let Some(encoder_node) = graph.used_to(cn[&id].1) else {
359	            result.unassigned.push(Unassigned {
360	                connector: id,
361	                reason: UnassignedReason::NoCompatibleRoute,
362	            });
363	            continue;
364	        };
365	        let encoder = *en
366	            .iter()
367	            .find(|(_, nodes)| nodes.0 == encoder_node)
368	            .expect("encoder node")
369	            .0;
370	        let crtc_node = graph.used_to(en[&encoder].1).expect("routed crtc");
371	        let crtc = *rn
372	            .iter()
373	            .find(|(_, nodes)| nodes.0 == crtc_node)
374	            .expect("crtc node")
375	            .0;
376	        let plane_node = graph.used_to(rn[&crtc].1).expect("routed plane");
377	        let plane = *pn
378	            .iter()
379	            .find(|(_, nodes)| nodes.0 == plane_node)
380	            .expect("plane node")
381	            .0;
382	        result.assignments.push(Assignment {
383	            connector: id,
384	            encoder,
385	            crtc,
386	            primary_plane: plane,
387	            mode_index: *index,
388	            mode: *mode,
389	            refresh_millihz: *refresh,
390	            candidate_formats: formats[&plane].clone(),
391	        });
392	    }
393	    result.unassigned.sort_by_key(|u| u.connector);
394	    Ok(result)
395	}
