450	    }
451	}
452	// Pause active DRM even when a later initialization step returns early. The
453	// guard is disarmed only when ownership moves into the prepared GPU domain.
454	struct PauseOnDrop<T> {
455	    resource: Option<T>,
456	    pause: fn(&mut T),
457	}
458	impl<T> PauseOnDrop<T> {
459	    fn new(resource: T, pause: fn(&mut T)) -> Self {
460	        Self {
461	            resource: Some(resource),
462	            pause,
463	        }
464	    }
465	    fn disarm(mut self) -> T {
466	        self.resource.take().expect("pending resource owned")
467	    }
468	}
469	impl<T> std::ops::Deref for PauseOnDrop<T> {
470	    type Target = T;
471	    fn deref(&self) -> &T {
472	        self.resource.as_ref().expect("pending resource owned")
473	    }
474	}
475	impl<T> Drop for PauseOnDrop<T> {
476	    fn drop(&mut self) {
477	        if let Some(resource) = &mut self.resource {
478	            (self.pause)(resource);
479	        }
480	    }
481	}
482	// Apply the pause before any fields retire. This suppresses Smithay's implicit
483	// active-device KMS restore on Changed/Removed/stop; no surfaces exist yet.
484	fn retire_paused<T>(resource: Option<T>, pause: impl FnOnce(&mut T)) {
485	    if let Some(mut resource) = resource {
486	        pause(&mut resource);
487	    }
488	}
489	impl<D: 'static> Kernel<D> {
490	    fn failure(device: Option<u64>, stage: Stage) -> NativeEvent {
491	        NativeEvent::Failure {
492	            device,
493	            error: Failure::at(stage),
494	        }
495	    }
496	    fn retire(&mut self, id: u64) {
497	        // Hotplug must not restore a connector snapshot captured before change.
498	        retire_paused(self.gpus.remove(&id), |gpu| {
499	            if gpu.drm.is_active() {
500	                gpu.drm.pause();
501	            }
502	        });
503	    }
504	    fn stop(&mut self) {
505	        self.model.stop();
506	        if let Some(input) = &mut self.input {
507	            input.suspend();
508	        }
509	        self.input_token.take();
510	        self.input.take();
511	        let devices: Vec<_> = self.gpus.keys().copied().collect();
512	        for id in devices {
513	            self.retire(id);
514	        }
515	        self.paths.clear();
516	    }
517	    fn pause(&mut self) -> Vec<NativeEvent> {
518	        match self.model.pause() {
519	            Ok(false) => vec![],
520	            Ok(true) => {
521	                if let Some(input) = &mut self.input {
522	                    input.suspend();
523	                }
524	                for gpu in self.gpus.values_mut() {
525	                    gpu.drm.pause();
526	                }
527	                vec![NativeEvent::SessionActive(false)]
528	            }
529	            Err(_) => {
530	                self.stop();
531	                vec![
532	                    Self::failure(None, Stage::Lifecycle),
533	                    NativeEvent::SessionActive(false),
534	                ]
535	            }
536	        }
537	    }
538	    fn activate(&mut self, weak: &Weak<RefCell<Self>>) -> Vec<NativeEvent> {
539	        match self.model.activate() {
540	            Ok(false) => return vec![],
541	            Ok(true) => (),
542	            Err(_) => {
543	                self.stop();
544	                return vec![
545	                    Self::failure(None, Stage::Lifecycle),
546	                    NativeEvent::SessionActive(false),
547	                ];
548	            }
549	        }
550	        let input_result = if let Some(input) = &mut self.input {
551	            input.resume().map_err(|_| Failure::at(Stage::InputResume))
552	        } else {
553	            self.init_input(weak)
554	        };
555	        if let Err(error) = input_result {
556	            self.stop();
557	            return vec![
558	                NativeEvent::Failure {
559	                    device: None,
560	                    error,
561	                },
562	                NativeEvent::SessionActive(false),
563	            ];
564	        }
565	        let mut events = vec![NativeEvent::SessionActive(true)];
566	        let ids: Vec<_> = self.paths.keys().copied().collect();
567	        for id in ids {
568	            if self.gpus.contains_key(&id) {
569	                self.retire(id);
570	                events.push(NativeEvent::GpuRemoved(id));
571	            }
572	            events.extend(self.prepare(id, weak));
573	        }
574	        events
575	    }
576	    fn init_input(&mut self, weak: &Weak<RefCell<Self>>) -> Result<(), Failure> {
577	        let mut input =
578	            Libinput::new_with_udev::<LibinputSessionInterface<InputSession<LibSeatSession>>>(
579	                InputSession {
580	                    session: self.session.clone(),
581	                    close_failures: self.close_failures.clone(),
582	                }
583	                .into(),
584	            );
585	        input
586	            .udev_assign_seat(&self.session.seat())
587	            .map_err(|_| Failure::at(Stage::InputSetup))?;
588	        let source = LibinputInputBackend::new(input.clone());
589	        let weak = weak.clone();
590	        let seat_owner = self.seat_owner.clone();
591	        let handle = (self.handle)().ok_or_else(|| Failure::at(Stage::SourceRegistration))?;
592	        let token = handle
593	            .insert_source(
594	                source,
595	                pin_lease(seat_owner, move |event, _, data| {
596	                    let Some(kernel) = weak.upgrade() else { return };
597	                    let notify = {
598	                        let k = kernel.borrow();
599	                        if !k.model.active() {
600	                            return;
601	                        };
602	                        k.notify.clone()
603	                    };
604	                    notify(NativeEvent::Input(event), data);
605	                }),
606	            )
607	            .map_err(|_| Failure::at(Stage::SourceRegistration))?;
608	        self.input = Some(input);
609	        self.input_token = Some(Registration::new(self.handle.clone(), token));
610	        Ok(())
611	    }
612	    fn udev(&mut self, event: UdevEvent, weak: &Weak<RefCell<Self>>) -> Vec<NativeEvent> {
613	        if self.model.closed() {
614	            return vec![];
615	        }
616	        let id = match &event {
617	            UdevEvent::Added { device_id, .. }
618	            | UdevEvent::Changed { device_id }
619	            | UdevEvent::Removed { device_id } => *device_id,
620	        };
621	        let result = match event {
622	            UdevEvent::Added { path, .. } => match self.model.discover(id) {
623	                Ok(false) => return vec![],
624	                Ok(true) => {
625	                    self.paths.insert(id, path);
626	                    Ok(())
627	                }
628	                Err(e) => Err(e),
629	            },
630	            UdevEvent::Changed { .. } => {
631	                if !self.paths.contains_key(&id) {
632	                    return vec![];
633	                }
634	                self.model.changed(id)
635	            }
636	            UdevEvent::Removed { .. } => {
637	                self.retire(id);
638	                self.paths.remove(&id);
639	                return match self.model.remove(id) {
640	                    Ok(true) => vec![NativeEvent::GpuRemoved(id)],
641	                    Ok(false) => vec![],
642	                    Err(_) => vec![Self::failure(Some(id), Stage::Lifecycle)],
643	                };
644	            }
645	        };
646	        if result.is_err() {
647	            if self.model.closed() {
648	                self.stop();
649	                return vec![
650	                    Self::failure(Some(id), Stage::Lifecycle),
651	                    NativeEvent::SessionActive(false),
652	                ];
653	            }
654	            return vec![Self::failure(Some(id), Stage::Lifecycle)];
655	        }
656	        let mut events = vec![];
657	        if self.gpus.contains_key(&id) {
658	            self.retire(id);
659	            events.push(NativeEvent::GpuRemoved(id));
660	        }
661	        if self.model.active() {
662	            events.extend(self.prepare(id, weak));
663	        }
664	        events
665	    }
