    fn graph(mask: u16) -> Topology {
        let links = |shift, id| {
            (0..2)
                .filter(|target| mask & (1u16 << (shift + id * 2 + target)) != 0)
                .map(|target| target + 1)
                .collect()
        };
        Topology {
            connectors: (0..2)
